const sketch = (p5obj:any) => {
/**
 繧ｷ繧ｧ繝ｫ繝斐Φ繧ｹ繧ｭ繝ｼ縺ｮ繧ｮ繝｣繧ｹ繧ｱ繝・ヨ繧剃ｽｿ縺｣縺滓凾險・
 
 譎る俣・悟・・檎ｧ偵・縺昴ｌ縺槭ｌ蛻晄悄繝峨ャ繝医ｒ荳逡ｪ荳翫↓謇薙▽.
 
 */
let cell: number[][] = new Array(600).fill([]).map(() => new Array(300));       // 繧ｹ繧ｯ繝ｪ繝ｼ繝ｳ繧ｵ繧､繧ｺ蛻・・驟榊・.
let iFPS: number = 4;         // fps

let iFrameIdx: number;         // 繝輔Ξ繝ｼ繝逡ｪ蜿ｷ:0~iFPS

p5obj.setup = () => 
{
  p5obj.createCanvas(600, 300);
  p5obj.colorMode(p5obj.HSB, 6, 1, 1 );
  p5obj.frameRate( iFPS );

  // 驟榊・縺ｮ蛻晄悄蛹・
  for (let iX: number = 0; iX<cell.length; iX++)
  {
    for (let iY: number = 0; iY<cell[iX].length; iY++)
    {
      cell[iX][iY]=0;
    }
  }
  iFrameIdx = 0;
}

p5obj.draw = () => 
{
  p5obj.fill(0, 0, 0.5);
  p5obj.noStroke();
  p5obj.rect(0, 0, p5obj.width, p5obj.height);  // 繧ｹ繧ｯ繝ｪ繝ｼ繝ｳ繝ｪ繝輔Ξ繝・す繝･

  let iSecond: number = p5obj.second();
  let iDrawXSec: number = p5obj.floor( p5obj.width * ( iSecond / 60.0 ) );

  let iMinute: number = p5obj.minute();
  let iDrawXMin: number = p5obj.floor( p5obj.width * ( iMinute / 60.0 ) );

  let iHour: number = p5obj.hour();
  let iDrawXHour: number = p5obj.floor( p5obj.width * ( iHour / 24.0 ) );

  let iDrawXFrame: number = p5obj.floor( p5obj.width * ( iFrameIdx / iFPS ) );

  // 蛻晄悄迥ｶ諷具ｼ・
  for (let iX: number = 0; iX<p5obj.width; iX++)
  {
    if ( iX==iDrawXSec )
    {
      cell[iX][0]= 1;
    }
    else if ( iX==iDrawXMin )
    {
      cell[iX][0]= 3;
    }
    else if ( iX==iDrawXHour )
    {
      cell[iX][0]= 5;
    }
    else if ( iX==iDrawXFrame )
    {
      cell[iX][0]= 0;
    }
    else
    {
      cell[iX][0]= 0;
    }
  }

  for (let iY: number = 1; iY<p5obj.height; iY++)  // ・定｡檎岼縺九ｉ郢ｰ繧願ｿ斐＠髢句ｧ具ｼ・
  {
    for (let iX: number = 0; iX<p5obj.width; iX++)
    {
      if ( iX == 0 )             // 繧ｹ繧ｯ繝ｪ繝ｼ繝ｳ蟾ｦ遶ｯ縺ｮ蜃ｦ逅・
      {
        cell[iX][iY] = ( 0 + cell[iX+1][iY-1] )%6;
      }
      else if ( iX == p5obj.width-1 )  // 繧ｹ繧ｯ繝ｪ繝ｼ繝ｳ蜿ｳ遶ｯ縺ｮ蜃ｦ逅・
      {
        cell[iX][iY] = ( cell[iX-1][iY-1] + 0 )%6;
      }
      else
      {
        // 髫｣謗･縺吶ｋ繧ｻ繝ｫ縺ｮ蜷郁ｨ・
        cell[iX][iY] = ( cell[iX-1][iY-1] + cell[iX+1][iY-1] )%6;
      }

      if ( cell[iX][iY] > 0 )    // 繧ゅ＠繧ゅそ繝ｫ縺ｮ蛟､縺・莉･荳翫↑繧・
      {

        if ( cell[iX][iY]==5 )
        {
          p5obj.stroke( 0, 0, 1 );
        }
        else if ( cell[iX][iY]==1 )
        {
          p5obj.stroke( 0, 0, 1 );
        }
        p5obj.stroke( 0, 0, 1 );
        p5obj.point( iX, iY );
      }
      else
      {
        p5obj.stroke( 0, 0, (iX/p5obj.width)*(iY/p5obj.height)-0.2 );
        p5obj.point( iX, iY );
      }
    }
  }

  // 繝輔Ξ繝ｼ繝繧｢繝九Γ逕ｨ螟画焚譖ｴ譁ｰ.
  if ( iFrameIdx >= iFPS )
  {
    iFrameIdx = 0;
  }
  else
  {
    iFrameIdx++;
  }
}

};

export default sketch;
