const sketch = (p5obj:any) => {
/**

縺励＠縺翫←縺励ｒ陦ｨ迴ｾ縺励◆譎りｨ医・
遘偵＃縺ｨ縺ｫ髮ｫ縺瑚誠縺｡縲∝・縺斐→縺ｫ縺励＠縺翫←縺励′蜍輔″縲∵凾髢薙＃縺ｨ縺ｫ螟ｪ髯ｽ縲∵怦縲∫ｩｺ縺ｮ濶ｲ縺ｪ縺ｩ縺悟､牙喧縺吶ｋ縲よ悃辟ｼ縺代∝､慕┥縺代ｂ陦ｨ迴ｾ縺励※縺・ｋ縲・

**/

let iX: number = 0;
let iY: number = 0;
let iZ: number = 0;

p5obj.setup = () => 
{
  p5obj.createCanvas(500,500);
  p5obj.frameRate(60);
}

p5obj.draw = () => 
{
  drawbackground();
  drawbackground2();
  drawsun();
  drawmoon();
  drawground();
  drawkakehi();
  drawhachi();
  drawshishiodoshi();
  drawwater();
  drawlight();
}

//遨ｺ縺ｮ譏弱ｋ縺輔ｒ陦ｨ迴ｾ縺吶ｋ髢｢謨ｰ縲よ悃縺ｨ螟懊↓濶ｲ縺・144,215,236)縺・0,0,80)縺ｫ螟牙喧縺吶ｋ
const drawbackground = () => {
  let iB: number = p5obj.second()+60*p5obj.minute()+3600*p5obj.hour();
  
  if ( 4 <= p5obj.hour() && p5obj.hour() < 8)
  {
    p5obj.background( (iB-14400)*144/14400 ,(iB-14400)*215/14400 ,80+(iB-14400)*156/14400);    
  }
  else if ( 8 <= p5obj.hour() && p5obj.hour() < 16 )
  {
    p5obj.background(144,215,236);
  }
  else if (16 <= p5obj.hour() && p5obj.hour() < 20)
  {
    p5obj.background( 144-(iB-57600)*144/14400 ,215-(iB-57600)*215/14400 ,236-(iB-57600)*156/14400);
  }
  else
  {
    p5obj.background(0,0,80);
  }
}

//譛晉┥縺代∝､慕┥縺代ｒ陦ｨ迴ｾ縺吶ｋ髢｢謨ｰ縲よｨｪ縺ｮline繧定､・焚邵ｦ縺ｫ蠑輔￥縺薙→縺ｧ逋ｽ竊定ｵ､縺ｮ繧ｰ繝ｩ繝・・繧ｷ繝ｧ繝ｳ繧定｡ｨ迴ｾ縺励※縺・ｋ縲・
//縺昴・縺ｾ縺ｾ繧ｰ繝ｩ繝・・繧ｷ繝ｧ繝ｳ縺ｫ縺吶ｋ縺ｨ荳崎・辟ｶ縺ｪ縺ｮ縺ｧ縲《in繧偵°縺ｾ縺帙ｋ縺薙→縺ｧ蝨ｰ髱｢縺ｫ霑代▼縺上⊇縺ｩ譖ｴ縺ｫ襍､縺上↑繧九ｈ縺・↓
//荳埼乗・蠎ｦ繧呈凾髢薙↓蜷医ｏ縺帙※螟峨∴繧九％縺ｨ縺ｧ螟ｪ髯ｽ縺ｮ豬ｮ縺肴ｲ医∩繧貞・迴ｾ
const drawbackground2 = () => {
  let iB: number = p5obj.second()+60*p5obj.minute()+3600*p5obj.hour();
  for (let y: number = 100; y <= 250; y ++)
  {
    let ia: number = p5obj.sin(p5obj.radians( (y-100)*90/150 ));
    if( 4 <= p5obj.hour() && p5obj.hour() < 6 )
    {
      p5obj.stroke( 255, 255-ia*(y-100)*87/150, 255-ia*(y-100)*141/150,ia*((y-100)*255/150)*(iB-14400)/7200);
    }
    else if( 6 <= p5obj.hour() && p5obj.hour() < 8 )
    {
      p5obj.stroke( 255, 255-ia*(y-100)*87/150, 255-ia*(y-100)*141/150,ia*((y-100)*255/150)*(1-(iB-21600)/7200));
    }
    else if( 16 <= p5obj.hour() && p5obj.hour() < 18 )
    {
      p5obj.stroke( 255, 255-ia*(y-100)*87/150, 255-ia*(y-100)*141/150,ia*((y-100)*255/150)*(iB-57600)/7200);
    }
    else if( 18 <= p5obj.hour() && p5obj.hour() < 20 )
    {
      p5obj.stroke( 255, 255-ia*(y-100)*87/150, 255-ia*(y-100)*141/150,ia*((y-100)*255/150)*(1-(iB-64800)/7200));
    }
    else
    {
      p5obj.stroke(0,0,0,0);
    }
    p5obj.line(0,y,500,y);
  }
}

//荳譌･繧堤ｧ呈焚縺ｧ陦ｨ縺励※縺ｪ繧九∋縺上↑繧√ｉ縺九↓・抵ｼ疲凾髢薙〒螟ｪ髯ｽ縺ｨ譛医ｒ荳蜻ｨ縺輔○繧矩未謨ｰ,12譎ゅ↓螟ｪ髯ｽ縺後・4譎ゅ↓譛医′荳翫↓縺・￥繧医≧縺ｫ
const drawsun = () => {
  p5obj.noStroke();
  p5obj.fill(255,148,119);
  p5obj.circle(250+200*p5obj.cos(p5obj.radians(90+(p5obj.second()+60*p5obj.minute()+3600*p5obj.hour())/240)),250+200*p5obj.sin(p5obj.radians(90+(p5obj.second()+60*p5obj.minute()+3600*p5obj.hour())/240)),40);
}

const drawmoon = () => {
  p5obj.fill(255,255,163); 
  p5obj.circle(250+200*p5obj.cos(p5obj.radians(270+(p5obj.second()+60*p5obj.minute()+3600*p5obj.hour())/240)),250+200*p5obj.sin(p5obj.radians(270+(p5obj.second()+60*p5obj.minute()+3600*p5obj.hour())/240)),40);
}

//蝨ｰ髱｢繧定｡ｨ迴ｾ縺吶ｋ髢｢謨ｰ縲・
const drawground = () => {
  p5obj.fill(100,100,100);
  p5obj.rect(0,250,500,250);
}

//遲ｧ・域ｰｴ縺悟・繧区園・峨ｒ陦ｨ迴ｾ縺吶ｋ髢｢謨ｰ縲・
const drawkakehi = () => {
  p5obj.stroke(0,0,0,50);
  p5obj.fill(130,172,35);
  p5obj.rect(60,110,15,300);
  p5obj.fill(145,141,64);
  p5obj.beginShape();
  p5obj.vertex(100,70);
  p5obj.vertex(100,120);
  p5obj.vertex(40,130);
  p5obj.vertex(35,125);
  p5obj.vertex(35,75);
  p5obj.vertex(95,65);
  p5obj.endShape(p5obj.CLOSE);
  p5obj.fill(130,172,35);
  p5obj.beginShape();
  p5obj.vertex(70,90);
  p5obj.vertex(200,140);
  p5obj.vertex(200,160);
  p5obj.vertex(70,110);
  p5obj.endShape();
  p5obj.fill(222,184,135);
  p5obj.ellipse(200,150,10,20);
}

//豌ｴ縺ｮ蜈･縺｣縺ｦ縺・ｋ驩｢繧定｡ｨ迴ｾ縺吶ｋ髢｢謨ｰ縲・
const drawhachi = () => {
  p5obj.fill(40,70,70);
  p5obj.ellipse(175,410,290,230);
  p5obj.ellipse(175,352,270,120);
  p5obj.fill(40,100,110);
  p5obj.ellipse(175,350,240,100);
}

//縺励＠縺翫←縺励ｒ陦ｨ迴ｾ縺吶ｋ髢｢謨ｰ縲・
const drawshishiodoshi = () => {
  p5obj.fill(130,172,35);
  p5obj.rect(340,335,24,215);
  p5obj.fill(128,128,128);
  p5obj.ellipse(455,495,350,100);
  p5obj.ellipse(470,460,250,80);
  p5obj.fill(130,172,35);

  p5obj.push();

  //縺励＠縺翫←縺励ｒ・大・邨後▽縺斐→縺ｫ蜍輔°縺吶・ｼ皮ｧ偵∪縺ｧ縺ｯ蝗櫁ｻ｢縺励√◎繧御ｻ･髯阪・蜈・↓謌ｻ繧九ｈ縺・↓
  p5obj.translate(337,355);
  if( 0 <= p5obj.second() && p5obj.second() < 4 )
  {
    p5obj.rotate(p5obj.radians(-iY/8));
    iY ++;
  }
  else if( 4 <= p5obj.second() && p5obj.second() < 5 )
  {
    p5obj.rotate(p5obj.radians(-iY/8));
  }
  else if( 5 <= p5obj.second() && iY/8>iZ )
  {
    p5obj.rotate(p5obj.radians(iZ-iY/8));
    iZ +=2 ;
  }
  else
  {
    iY = 0;
    iZ = 0;
  }

  p5obj.beginShape();
  p5obj.vertex(192-337,288-355);
  p5obj.vertex(260-337,287-355);
  p5obj.vertex(484-337,417-355);
  p5obj.vertex(460-337,447-355);
  p5obj.endShape(p5obj.CLOSE);
  p5obj.fill(222,184,135);
  p5obj.ellipse(226-337,287-355,69,11);
  //縺励＠縺翫←縺励′蛟偵ｌ蛻・▲縺滓凾縺縺第ｰｴ縺梧ｵ√ｌ縺ｦ縺・ｋ繧医≧縺ｫ隕九○繧・
  if( 3 <= p5obj.second() && p5obj.second() < 4 )
  {
    p5obj.fill(100,150,160,125);
    p5obj.arc(201-337,287-355,20,6,p5obj.radians(100),p5obj.radians(270));
  }
  else if( 4 <= p5obj.second() && p5obj.second() < 5 )
  {
    p5obj.fill(100,150,160);
    p5obj.arc(205-337,287-355,25,6,p5obj.radians(90),p5obj.radians(270));
  }
  p5obj.pop();
  
  p5obj.fill(130,172,35);
  p5obj.rect(310,340,30,210);
  p5obj.fill(218,165,32);
  p5obj.circle(325,360,5);
}

//豌ｴ縺ｮ關ｽ縺｡譁ｹ縺ｮ陦ｨ迴ｾ縲∫ｭｧ縺ｮ蜈育ｫｯ縺九ｉ蜃ｺ縺ｦ縺励＠縺翫←縺励・蜈育ｫｯ縺ｫ蠖薙◆縺｣縺溘ｉ豸医∴繧九ｈ縺・↓
const drawwater = () => {
  let iA: number;
  iA = 157+9.8*iX*iX/100 ;
  iX++ ;
  if (iA < 285)
  //157縺ｯ遲ｧ縺ｮy蠎ｧ讓吶・85縺ｯ縺励＠縺翫←縺励・y蠎ｧ讓・
  {
  p5obj.fill(135,206,235);
  p5obj.circle(200,iA,6);
  }
  else if (iX > 60)
  //繝輔Ξ繝ｼ繝繝ｬ繝ｼ繝医′60縺ｪ縺ｮ縺ｧ60縺ｫ縺ｪ繧九＃縺ｨ縺ｫ繝ｪ繧ｻ繝・ヨ縺・遘偵ｒ陦ｨ迴ｾ縺吶ｋ
  {
    iX = 0 ;
  }
}

//譏ｼ縺ｮ髢薙・蜊企乗・縺ｮ鮟・牡繧偵・縺帙※縺繧薙□繧捺・繧九￥縲∝､懊・髢薙・蜈ｨ菴薙↓蜊企乗・縺ｮ繧ｰ繝ｬ繝ｼ繧偵・縺帙※縺繧薙□繧捺囓縺上↑繧九ｈ縺・↓
const drawlight = () => {
  let iB: number = p5obj.second()+60*p5obj.minute()+3600*p5obj.hour();
  if ( 4 <= p5obj.hour() && p5obj.hour() < 8 )
  {
    p5obj.fill(0,0,0,100-(iB-14400)*100/14400);
  }
  else if ( 8 <= p5obj.hour() && p5obj.hour() < 12 )
  {
    p5obj.fill(255,255,255,(iB-28800)*40/14400);
  }
  else if ( 12 <= p5obj.hour() && p5obj.hour() < 16 )
  {
    p5obj.fill(255,255,255,40-(iB-43200)*40/14400);
  }
  else if ( 16 <= p5obj.hour() && p5obj.hour() < 20 )
  {
    p5obj.fill(0,0,0,(iB-57600)*100/14000);
  }
  else
  {
    p5obj.fill(0,0,0,100);
  }
  p5obj.square(0,0,500);
}

};

export default sketch;
