const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.RGB, 256, 256, 256, 0.1);
p5obj.background(66, 20, 33);
var a = 25; //豁｣譁ｹ蠖｢縺ｮ螟ｧ縺阪＆繧呈欠螳・
var b = a/3*2;//3蛻・・2縺ｮ霎ｺ
var c  =a/3; //3蛻・・1縺ｮ霎ｺ
var r = a*p5obj.sin(120); //荳芽ｧ貞ｽ｢縺ｮ鬮倥＆
p5obj.translate(-a, a+r*0.3);//蜈･繧悟ｭ舌・繧ｺ繝ｬ

for (var pt=0; pt<3; pt++)  //2縺､縺ｮ蝗ｳ譟・ｒ・灘屓郢ｰ繧願ｿ斐☆
{
  //蝗ｳ譟・
  for (var y=0; y<2; y++)       //邵ｦ縺ｫ2郢ｰ繧願ｿ斐＠
  {
    for (var x=0; x<10; x++)      //讓ｪ縺ｫ10郢ｰ繧願ｿ斐＠
    {
      p5obj.translate(a*2, 0);

      for (var i=0; i<4; i++)   //1繝悶Ο繝・け繧・蝗樒ｹｰ繧願ｿ斐＠
      {
        p5obj.noStroke();
        p5obj.rotate(p5obj.PI/2);//隗貞ｺｦ繧・0蠎ｦ螟峨∴繧・
        //濶ｲ縲∝､ｧ縺阪＆縺ｮ驕輔≧荳画ｮｵ縺ｮ荳芽ｧ貞ｽ｢繧剃ｽ懈・
        //驟崎牡1
        p5obj.fill(235, 212, 134); //繧ｯ繝ｪ繝ｼ繝
        p5obj.triangle(0, 0, 0, a, a, a);
        p5obj.fill(66, 20, 33); //辟ｦ闌ｶ
        p5obj.triangle(0, 0, 0, b, b, b);
        p5obj.fill(235, 212, 134);//繧ｯ繝ｪ繝ｼ繝
        p5obj.triangle(0, 0, 0, c, c, c);
        //驟崎牡2
        p5obj.fill(132, 54, 26); //闌ｶ
        p5obj.triangle(0, 0, a, 0, a, a);
        p5obj.fill(217, 152, 67); //繝吶・繧ｸ繝･
        p5obj.triangle(0, 0, b, 0, b, b);
        p5obj.fill(132, 54, 26);//闌ｶ
        p5obj.triangle(0, 0, c, 0, c, c);
      }
    }
    p5obj.translate(-500, 0); //X蠎ｧ讓吶ｒ蟾ｦ遶ｯ縺ｫ謌ｻ縺・
    p5obj.translate(0, 50); //Y蠎ｧ讓吶ｒ荳谿ｵ荳九￡繧・
  }

  p5obj.translate(a, r*0.6);//蝗ｳ譟・→蝗ｳ譟・・諢溯ｦ壹ｒ髢九￠繧・

  //蝗ｳ譟・
  for (var y=0; y<2; y++)//邵ｦ縺ｫ2蛟・
  {
    for (var x=0; x<21; x++)//讓ｪ縺ｫ10蛟玖､・｣ｽ
    {
      for (var tri = 0; tri<3; tri++)//豁｣荳芽ｧ貞ｽ｢繧剃ｸ牙・蜑ｲ縺吶ｋ
      {
        p5obj.stroke(66, 20, 33);
        p5obj.fill(217, p5obj.random(150, 165), 67);
        p5obj.triangle(0, 0, -a, r, a, r);
        p5obj.rotate(p5obj.radians(120));
      }
      p5obj.scale(1, -1);  //隍・｣ｽ縺吶ｋ縺斐→縺ｫ荳贋ｸ九ｒ蜿崎ｻ｢縺吶ｋ
      p5obj.translate(a, r); //讓ｪ縺ｫ遘ｻ蜍輔∝渚霆｢譎ゅ・荳贋ｸ九・繧ｺ繝ｬ
    }
    p5obj.translate(-525, 0);
    p5obj.translate(0, -50+(r/2));
  }
  p5obj.translate(-a, 100-r*0.9);
}

  };
};

export default sketch;
