const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(1000,1000);
  p5obj.noLoop();
}

p5obj.draw = () => 
{
  p5obj.fill(250);
  p5obj.background('#1D4C4D');
  p5obj.strokeWeight(15);

  p5obj.text("forest",20,20);
  p5obj.fill(250);
  p5obj.textSize(600);

  for(let i: number = -300; i<=500;i+=80)
  {
    p5obj.push();
    p5obj.translate(p5obj.width/5+i,p5obj.height);
    branch(0);
    p5obj.pop();
  }
}

const branch = (depth: number) => {
  if(depth<11)
  {
    p5obj.line(3,2,2,-p5obj.height/10);
    {
      p5obj.translate(0,-p5obj.height/15);
      p5obj.rotate(p5obj.random(-0.1,0.1));

      if(p5obj.random(1.0)<0.4)
      {  
        p5obj.rotate(0.4);
        p5obj.scale(0.7);
        p5obj.push();
        branch(depth+1);
        p5obj.pop();
        p5obj.rotate(-0.6);
        p5obj.push();
        branch(depth+1);
        p5obj.pop();
      }
      else
      {
        branch(depth);
      }
    }
  }
  else
  {
    p5obj.noStroke();
    p5obj.fill('#4C7C6F');
    p5obj.ellipse(0,0,p5obj.random(100,300),p5obj.random(100,300));
    p5obj.stroke(0);
  
    p5obj.fill('#94AF77');
    p5obj.ellipse(30,60,p5obj.random(70,90),p5obj.random(70,90));
  
    p5obj.fill('#1C765C');
    p5obj.ellipse(100,100,p5obj.random(60,80),p5obj.random(60,80));
  
    p5obj.fill('#094C4D');
    p5obj.ellipse(500,500,p5obj.random(100,120),p5obj.random(100,120));
  
    p5obj.fill('#13392F');
    p5obj.ellipse(900,500,p5obj.random(30,50),p5obj.random(30,50));
  }
}

};

export default sketch;
